+};
+
+#define ANIMATION_COUNT (sizeof(g_animations) / sizeof(g_animations[0]))
+
+static void print_usage(void)
+{
+    printf("Usage: emoji_demo <name|index|next|stop|list>\n");
+    printf("  name  02, 03, drink, exercise, listen, or speak\n");
+    printf("  index 0-%u, select an animation by index\n",
+           (unsigned)ANIMATION_COUNT - 1);
+    printf("  next  play the next animation in the demo list\n");
+    printf("  stop  stop the current animation\n");
+    printf("  list  print animation names\n");
+}
+
+static void print_animations(void)
+{
+    unsigned int i;
+
+    for (i = 0; i < ANIMATION_COUNT; i++)
+        printf("%u: %s\n", i, g_animations[i]);
+}
+
+int main(int argc, char *argv[])
+{
+    const char *name;
+    char *end;
+    unsigned long index;
+    int ret;
+
+    if (argc != 2) {
+        print_usage();
+        return 1;
+    }
+
+    if (strcmp(argv[1], "list") == 0) {
+        print_animations();
+        return 0;
+    }
+
+    if (strcmp(argv[1], "stop") == 0) {
+        ret = home_scense_emoji_stop();
+        if (ret < 0) {
+            printf("emoji_demo: stop failed: %d (%s)\n", ret,
+                   strerror(-ret));
+            return 1;
+        }
+
+        printf("emoji_demo: stop requested\n");
+        return 0;
+    }
+
+    if (strcmp(argv[1], "next") == 0) {
+        /* The home screen advances its automatic sequence on each request. */
+        name = NULL;
+        ret = home_scense_emoji_play("next");
+        if (ret == 0) {
+            printf("emoji_demo: next requested\n");
+            return 0;
+        }
+
+        /* "next" is not a resource name; select a deterministic demo item. */
+        name = g_animations[0];
+        ret = home_scense_emoji_play(name);
+        if (ret < 0) {
+            printf("emoji_demo: next failed: %d (%s)\n", ret,
+                   strerror(-ret));
+            return 1;
+        }
+
+        printf("emoji_demo: playing %s\n", name);
+        return 0;
+    }
+
+    index = strtoul(argv[1], &end, 10);
+    if (*argv[1] != '\0' && *end == '\0' && index < ANIMATION_COUNT)
+        name = g_animations[index];
+    else
+        name = argv[1];
+
+    ret = home_scense_emoji_play(name);
+    if (ret < 0) {
+        printf("emoji_demo: play failed: %d (%s)\n", ret, strerror(-ret));
+        return 1;
+    }
+
+    printf("emoji_demo: playing %s\n", name);
