1	/****************************************************************************
2	 * app/home_scense/doubao/doubao_protocol.c
3	 * Doubao RealtimeAPI binary envelope helpers.
4	 ****************************************************************************/
5	
6	#include "doubao_protocol.h"
7	
8	#include <ctype.h>
9	#include <errno.h>
10	#include <stdio.h>
11	#include <stdlib.h>
12	#include <string.h>
13	
14	#define DOUBAO_VERSION_HEADER_4      0x11
15	#define DOUBAO_FULL_CLIENT_EVENT     0x14
16	#define DOUBAO_AUDIO_CLIENT_EVENT    0x24
17	#define DOUBAO_FULL_SERVER_EVENT     0x90
18	#define DOUBAO_AUDIO_SERVER_EVENT    0xb0
19	#define DOUBAO_ERROR_MESSAGE         0xf0
20	#define DOUBAO_SERIALIZATION_JSON    0x10
21	#define DOUBAO_SERIALIZATION_RAW     0x00
22	#define DOUBAO_NO_COMPRESSION         0x00
23	
24	static void write_u32(uint8_t *output, uint32_t value)
25	{
26	  output[0] = (uint8_t)(value >> 24);
27	  output[1] = (uint8_t)(value >> 16);
28	  output[2] = (uint8_t)(value >> 8);
29	  output[3] = (uint8_t)value;
30	}
31	
32	static uint32_t read_u32(const uint8_t *input)
33	{
34	  return ((uint32_t)input[0] << 24) |
35	         ((uint32_t)input[1] << 16) |
36	         ((uint32_t)input[2] << 8) |
37	         (uint32_t)input[3];
38	}
39	
40	static int encode_event_packet(uint8_t message_type, uint8_t serialization,
41	                               int event, const char *session_id,
42	                               const uint8_t *payload, size_t payload_size,
43	                               uint8_t *output, size_t capacity,
44	                               size_t *output_size)
45	{
46	  size_t session_size;
47	  size_t needed;
48	  uint8_t *cursor;
49	
50	  if (!session_id || !output || !output_size ||
51	      (!payload && payload_size > 0) || payload_size > UINT32_MAX)
52	    {
53	      return -EINVAL;
54	    }
55	
56	  session_size = strlen(session_id);
57	  if (session_size > UINT32_MAX)
58	    {
59	      return -EOVERFLOW;
60	    }
61	
62	  /* Connection events omit the session-id field. */
63	  if (event == DOUBAO_EVENT_START_CONNECTION ||
64	      event == DOUBAO_EVENT_FINISH_CONNECTION)
65	    {
66	      session_size = 0;
67	      needed = 4 + 4 + 4 + payload_size;
68	    }
69	  else
70	    {
71	      needed = 4 + 4 + 4 + session_size + 4 + payload_size;
72	    }
73	
74	  if (capacity < needed)
75	    {
76	      return -EMSGSIZE;
77	    }
78	
79	  output[0] = DOUBAO_VERSION_HEADER_4;
80	  output[1] = message_type;
81	  output[2] = serialization | DOUBAO_NO_COMPRESSION;
82	  output[3] = 0;
83	  cursor = output + 4;
84	
85	  write_u32(cursor, (uint32_t)event);
86	  cursor += 4;
87	
88	  if (event != DOUBAO_EVENT_START_CONNECTION &&
89	      event != DOUBAO_EVENT_FINISH_CONNECTION)
90	    {
91	      write_u32(cursor, (uint32_t)session_size);
92	      cursor += 4;
93	      memcpy(cursor, session_id, session_size);
94	      cursor += session_size;
95	    }
96	
97	  write_u32(cursor, (uint32_t)payload_size);
98	  cursor += 4;
99	  if (payload_size > 0)
100	    {
101	      memcpy(cursor, payload, payload_size);
102	    }
103	
104	  *output_size = needed;
105	  return 0;
106	}
107	
108	int doubao_protocol_encode_json(int event, const char *session_id,
109	                                const char *json, uint8_t *output,
110	                                size_t capacity, size_t *output_size)
111	{
112	  if (!json)
113	    {
114	      return -EINVAL;
115	    }
116	
117	  return encode_event_packet(DOUBAO_FULL_CLIENT_EVENT,
118	                             DOUBAO_SERIALIZATION_JSON, event, session_id,
119	                             (const uint8_t *)json, strlen(json), output,
120	                             capacity, output_size);
121	}
122	
123	int doubao_protocol_encode_audio(int event, const char *session_id,
124	                                 const uint8_t *audio, size_t audio_size,
125	                                 uint8_t *output, size_t capacity,
126	                                 size_t *output_size)
127	{
128	  return encode_event_packet(DOUBAO_AUDIO_CLIENT_EVENT,
129	                             DOUBAO_SERIALIZATION_RAW, event, session_id,
130	                             audio, audio_size, output, capacity, output_size);
131	}
132	
133	int doubao_protocol_decode(const uint8_t *input, size_t input_size,
134	                           doubao_packet_t *packet)
135	{
136	  uint8_t message_type;
137	  uint8_t flags;
138	  const uint8_t *cursor;
139	  size_t remaining;
140	  uint32_t session_size;
141	  uint32_t payload_size;
142	
143	  if (!input || !packet || input_size < 8 || input[0] != DOUBAO_VERSION_HEADER_4)
144	    {
145	      return -EINVAL;
146	    }
147	
148	  message_type = input[1] & 0xf0;
149	  flags = input[1] & 0x0f;
150	  cursor = input + 4;
151	  remaining = input_size - 4;
152	  memset(packet, 0, sizeof(*packet));
153	
154	  if (message_type == DOUBAO_ERROR_MESSAGE)
155	    {
156	      if (remaining < 8)
157	        {
158	          return -EMSGSIZE;
159	        }
160	      packet->error_code = (int)read_u32(cursor);
161	      cursor += 4;
162	      remaining -= 4;
163	      packet->kind = DOUBAO_PACKET_ERROR;
164	    }
165	  else if (message_type == DOUBAO_FULL_SERVER_EVENT)
166	    {
167	      packet->kind = DOUBAO_PACKET_JSON;
168	    }
169	  else if (message_type == DOUBAO_AUDIO_SERVER_EVENT)
170	    {
171	      packet->kind = DOUBAO_PACKET_AUDIO;
172	    }
173	  else
174	    {
175	      return -EPROTO;
176	    }
177	
178	  if (flags & 0x01 || flags & 0x03)
179	    {
180	      if (remaining < 4)
181	        {
182	          return -EMSGSIZE;
183	        }
184	      packet->sequence = (int32_t)read_u32(cursor);
185	      cursor += 4;
186	      remaining -= 4;
187	    }
188	
189	  if (flags & 0x04)
190	    {
191	      if (remaining < 4)
192	        {
193	          return -EMSGSIZE;
194	        }
195	      packet->event = (int)read_u32(cursor);
196	      cursor += 4;
197	      remaining -= 4;
198	
199	      if (packet->event == DOUBAO_EVENT_CONNECTION_STARTED ||
200	          packet->event == 51 || packet->event == 52)
201	        {
202	          /* Connection events contain connect-id instead of session-id. */
203	          if (remaining < 4)
204	            {
205	              return -EMSGSIZE;
206	            }
207	          session_size = read_u32(cursor);
208	          cursor += 4;
209	          remaining -= 4;
210	          if (session_size > remaining)
211	            {
