1	/****************************************************************************
2	 * app/home_scense/doubao/voice_transport.c
3	 * Curl TLS + manual WebSocket for Doubao RealtimeAPI.
4	 ****************************************************************************/
5	
6	#include "voice_transport.h"
7	#include <curl/curl.h>
8	#include <errno.h>
9	#include <stdint.h>
10	#include <stdio.h>
11	#include <stdlib.h>
12	#include <string.h>
13	#include <strings.h>
14	#include <sys/select.h>
15	#include <sys/time.h>
16	#include <unistd.h>
17	
18	#define DOUBAO_ERR(fmt, ...) \
19	  do { FILE *_f=fopen("/tmp/doubao.log","a"); \
20	    if(_f){fprintf(_f,fmt"\n",##__VA_ARGS__);fclose(_f);} \
21	    fprintf(stderr,fmt"\n",##__VA_ARGS__); }while(0)
22	
23	#define WS_FIN 0x80u
24	#define WS_OPCODE_BINARY 0x02u
25	#define WS_OPCODE_CLOSE 0x08u
26	#define WS_OPCODE_PING 0x09u
27	#define WS_OPCODE_PONG 0x0Au
28	#define WS_MASK 0x80u
29	
30	struct voice_transport_s { CURL *curl; curl_socket_t fd; char logid[96]; uint8_t pbf[4096]; int pbf_len; };
31	
32	static ssize_t curl_send(CURL *c, const void *d, size_t n) {
33	  size_t s=0; CURLcode r=curl_easy_send(c,d,n,&s);
34	  return (r==CURLE_OK)?(ssize_t)s:-EIO; }
35	
36	static int curl_recv_to(CURL *c, curl_socket_t fd, void *b, size_t n, int ms) {
37	  struct timeval st,now,df; int el; size_t nr; CURLcode r;
38	  gettimeofday(&st,NULL);
39	  do { r=curl_easy_recv(c,b,n,&nr); if(r==CURLE_OK&&nr>0)return(int)nr;
40	    { fd_set f;struct timeval tv={0,20000};
41	      FD_ZERO(&f);FD_SET(fd,&f);select(FD_SETSIZE,&f,NULL,NULL,&tv); }
42	    gettimeofday(&now,NULL);timersub(&now,&st,&df);
43	    el=(int)(df.tv_sec*1000+df.tv_usec/1000);
44	  } while(el<ms);
45	  return 0; }
46	
47	/* 在 ms 超时内精确读满 n 字节(累加分段到达的字节)。
48	 * 返回 n=读满;0=整段超时且一个字节都没来(干净超时);-EIO=读到部分后中断。
49	 * 修复:此前 ws_recv 直接 curl_recv_to(hd,2,ms),若帧头分两次到达(先到 1
50	 * 字节)会 !=2 而误判 -EIO,进而被 voice_transport_receive 折叠成 0,让
51	 * run_turn 收 END_ASR 后第一次 recv 就"超时"退出,豆包回复漏进 idle 循环。 */
52	static int recv_exact(CURL *c, curl_socket_t fd, uint8_t *b, size_t n, int ms) {
53	  struct timeval st,now,df; int el; size_t got=0; CURLcode r; size_t nr;
54	  gettimeofday(&st,NULL);
55	  do {
56	    nr=0; r=curl_easy_recv(c,b+got,n-got,&nr);
57	    if(r==CURLE_OK&&nr>0){ got+=nr; if(got>=n)return(int)n; continue; }
58	    /* 连接关闭/出错:CURLE_OK 且 nr==0 是对端 EOF;非 AGAIN 是错误。
59	     * 两者都表示连接已死,立即返回 -ECONNRESET 触发上层重连,
60	     * 绝不能继续 select 空转(否则死循环疯狂重试 + 刷日志 → 崩溃)。 */
61	    if(r==CURLE_OK&&nr==0) return -ECONNRESET;
62	    if(r!=CURLE_AGAIN)     return -ECONNRESET;
63	    { fd_set f;struct timeval tv={0,20000};
64	      FD_ZERO(&f);FD_SET(fd,&f);select(FD_SETSIZE,&f,NULL,NULL,&tv); }
65	    gettimeofday(&now,NULL);timersub(&now,&st,&df);
66	    el=(int)(df.tv_sec*1000+df.tv_usec/1000);
67	  } while(el<ms);
68	  return got==0?0:-EIO; }
69	
70	static ssize_t curl_send_to(CURL *c, curl_socket_t fd, const void *d, size_t n, int ms) {
71	  struct timeval st,now,df; int el; ssize_t s;
72	  gettimeofday(&st,NULL);
73	  do { s=curl_send(c,d,n); if(s>0)return s;
74	    /* send failed: drain mbedTLS pending server data, poll socket, retry */
75	    { char sink[256]; size_t nr=0;
76	      curl_easy_recv(c, sink, sizeof(sink), &nr);
77	}
78	    { fd_set f;struct timeval tv={0,20000};
79	      FD_ZERO(&f);FD_SET(fd,&f);select(FD_SETSIZE,&f,NULL,NULL,&tv); }
80	    gettimeofday(&now,NULL);timersub(&now,&st,&df);
81	    el=(int)(df.tv_sec*1000+df.tv_usec/1000);
82	  } while(el<ms);
83	  return -EIO; }
84	
85	static int ws_upgrade(voice_transport_t *t, const voice_transport_config_t *cfg) {
86	  char req[1024],rsp[1024]; ssize_t tt=0,ln,ps;
87	  ln=snprintf(req,sizeof(req),
88	    "GET /api/v3/realtime/dialogue HTTP/1.1\r\n"
89	    "Host: openspeech.bytedance.com\r\n"
90	    "Upgrade: websocket\r\nConnection: Upgrade\r\n"
91	    "Sec-WebSocket-Key: dGhlIHNhbXBsZSBub25jZQ==\r\n"
92	    "Sec-WebSocket-Version: 13\r\n"
93	    "X-Api-App-ID: %s\r\nX-Api-Access-Key: %s\r\n"
94	    "X-Api-Resource-Id: %s\r\nX-Api-App-Key: %s\r\n"
95	    "%s%s%s\r\n",
96	    cfg->app_id,cfg->access_token,cfg->resource_id,cfg->app_key,
97	    cfg->connect_id?"X-Api-Connect-Id: ":"",
98	    cfg->connect_id?cfg->connect_id:"",
99	    cfg->connect_id?"\r\n":"");
100	  if(ln<0||(size_t)ln>=sizeof(req))return-EMSGSIZE;
101	  if(curl_send_to(t->curl,t->fd,req,(size_t)ln,5000)!=ln)return-EIO;
102	  while(tt<(ssize_t)(sizeof(rsp)-1)){
103	    ln=curl_recv_to(t->curl,t->fd,rsp+tt,sizeof(rsp)-1-(size_t)tt,8000);
104	    if(ln<=0){DOUBAO_ERR("doubao:WS timeout(%d)",(int)tt);return-EIO;}
105	    tt+=ln;rsp[tt]='\0';if(strstr(rsp,"\r\n\r\n"))break; }
106	  if(tt>=(ssize_t)(sizeof(rsp)-1))return-EMSGSIZE;
107	  { char*l=strcasestr(rsp,"X-Tt-Logid:");
108	    if(l){l+=10;while(*l==' '||*l=='\t')l++;
109	      for(ps=0;l[ps]&&l[ps]!='\r'&&l[ps]!='\n'&&ps<(ssize_t)(sizeof(t->logid)-1);ps++)
110	        t->logid[ps]=l[ps];t->logid[ps]='\0'; } }
111	  if(!strstr(rsp,"101")){ssize_t i;char s[256];
112	    size_t n=tt<(ssize_t)(sizeof(s)-1)?(size_t)tt:sizeof(s)-1;
113	    for(i=0;i<(ssize_t)n;i++)s[i]=rsp[i]>=0x20&&rsp[i]<=0x7e?rsp[i]:'.';
114	    s[n]='\0';DOUBAO_ERR("doubao:WS refused: %s",s);return-EIO;}
115	  return 0; }
116	
117	static int ws_send(CURL *c, curl_socket_t fd, const uint8_t *p, size_t sz) {
118	  uint8_t hd[14],mk[4],*m;size_t ps=2,tt,i; int ret=-EIO;
119	  hd[0]=WS_FIN|WS_OPCODE_BINARY;hd[1]=WS_MASK;
120	  if(sz<=125)hd[1]|=(uint8_t)sz;
121	  else if(sz<=65535){hd[1]|=126;hd[2]=(uint8_t)(sz>>8);hd[3]=(uint8_t)sz;ps=4;}
122	  else return-EMSGSIZE;
123	  tt=ps+4+sz;m=malloc(tt);if(!m)return-ENOMEM;
124	  memcpy(m,hd,ps);
125	  mk[0]=(uint8_t)(rand()&0xff);mk[1]=(uint8_t)(rand()&0xff);
126	  mk[2]=(uint8_t)(rand()&0xff);mk[3]=(uint8_t)(rand()&0xff);
127	  memcpy(m+ps,mk,4);
128	  for(i=0;i<sz;i++)m[ps+4+i]=p[i]^mk[i&3];
129	  if(curl_send_to(c,fd,m,tt,10000)==(ssize_t)tt)ret=0;
130	  else DOUBAO_ERR("doubao:ws send fail %zu",sz);
131	  free(m);return ret; }
132	
133	static int ws_recv(CURL *c, curl_socket_t fd, uint8_t *p, size_t cap, int ms) {
134	  uint8_t hd[2],op;uint64_t ln;size_t ps;int r;
135	  /* 帧头:读满 2 字节。干净超时(整个 ms 内无任何字节)返回 -ETIMEDOUT,
136	   * 供上层区分"暂时没数据"(继续等)与"真错误"。 */
137	  r=recv_exact(c,fd,hd,2,ms);
138	  if(r==0)return-ETIMEDOUT;
139	  if(r==-ECONNRESET)return-ECONNRESET;   /* 连接已死 → 上层重连 */
140	  if(r!=2)return-EIO;
141	  op=hd[0]&0x0f;ln=hd[1]&0x7f;if(hd[1]&WS_MASK)return-EIO;
142	  if(ln==126){uint8_t e[2];if(recv_exact(c,fd,e,2,5000)!=2)return-EIO;
143	    ln=((uint64_t)e[0]<<8)|e[1];}
144	  else if(ln==127){uint8_t e[8];uint32_t hi,lo;
145	    if(recv_exact(c,fd,e,8,5000)!=8)return-EIO;
146	    hi=((uint32_t)e[0]<<24)|((uint32_t)e[1]<<16)|((uint32_t)e[2]<<8)|e[3];
147	    lo=((uint32_t)e[4]<<24)|((uint32_t)e[5]<<16)|((uint32_t)e[6]<<8)|e[7];
148	    ln=(uint64_t)hi*0x100000000u+lo;}
149	  if(ln>cap)return-EMSGSIZE;
150	  if(ln>0){r=recv_exact(c,fd,p,(size_t)ln,5000);if(r!=(int)ln)return-EIO;}
151	  ps=(size_t)ln;
152	  switch(op){case WS_OPCODE_CLOSE:{
153	    /* 记录服务端关连接的状态码(payload 前 2 字节大端),定位为何频繁断开 */
154	    int code = (ln>=2)? (((int)p[0]<<8)|p[1]) : -1;
155	    DOUBAO_ERR("doubao:WS CLOSE code=%d len=%llu",code,(unsigned long long)ln);
156	    return-ECONNRESET;}
157	  case WS_OPCODE_PING:{
158	    /* WebSocket 要求客户端→服务端所有帧必须加掩码,并回显 PING 的
159	     * payload。此前回的 PONG 未加掩码(且丢了 payload),服务器判定协议
160	     * 违规 → 每隔几秒关连接,表现为豆包反复重连。这里用带掩码的 ws_send
161	     * 发 PONG(ws_send 内部已加掩码位+4字节掩码 key)。 */
162	    uint8_t mp[2]={WS_FIN|WS_OPCODE_PONG,WS_MASK}; uint8_t mk[4]; size_t i;
163	    uint8_t *fr; size_t frn;
164	    if(ln>125)return 0;                    /* 控制帧 payload ≤125,超出忽略 */
165	    mp[1]|=(uint8_t)ln;
166	    frn=2+4+(size_t)ln; fr=malloc(frn);
167	    if(!fr)return 0;
168	    fr[0]=mp[0]; fr[1]=mp[1];
169	    mk[0]=(uint8_t)(rand()&0xff);mk[1]=(uint8_t)(rand()&0xff);
170	    mk[2]=(uint8_t)(rand()&0xff);mk[3]=(uint8_t)(rand()&0xff);
171	    memcpy(fr+2,mk,4);
172	    for(i=0;i<(size_t)ln;i++)fr[6+i]=p[i]^mk[i&3];  /* 回显 PING payload */
173	    curl_send_to(c,fd,fr,frn,2000);
174	    free(fr);
175	    return 0;}
176	  case WS_OPCODE_BINARY:return(int)ps;default:return(int)ps;}
177	}
