202	
203	  r=ws_upgrade(t,cfg);if(r<0){voice_transport_close(t);return r;}
204	
205	  /* After ws_upgrade, drain leftover bytes (HTTP trailer garbage + first
206	   * real WS frame that were decrypted in the same TLS record). Save the
207	   * raw bytes — voice_transport_receive will skip the HTTP junk at front. */
208	  { size_t nr=0; t->pbf_len=0;
209	    while(t->pbf_len<4096&&curl_easy_recv(t->curl,t->pbf+t->pbf_len,
210	            sizeof(t->pbf)-t->pbf_len,&nr)==CURLE_OK&&nr>0)
211	      t->pbf_len+=(int)nr; }
212	
213	  DOUBAO_ERR("doubao:WS OK logid=%s",t->logid);*o=t;return 0; }
