394	/* 20ms 帧内 |sample| 均值,用于 barge-in VAD 与回声标定。 */
395	static unsigned frame_energy(const uint8_t *frame, size_t size)
396	{
397	  const int16_t *s = (const int16_t *)frame;
398	  size_t n = size / 2;
399	  uint64_t sum = 0;
400	
401	  if (n == 0)
402	    {
403	      return 0;
404	    }
405	  for (size_t i = 0; i < n; i++)
406	    {
407	      int v = s[i];
408	      sum += (uint64_t)(v < 0 ? -v : v);
409	    }
410	  return (unsigned)(sum / n);
411	}
412	
413	static bool energy_vad(const uint8_t *frame, size_t size, unsigned *run)
414	{
415	  if (frame_energy(frame, size) > DOUBAO_VAD_ON_THRESHOLD)
416	    {
417	      (*run)++;
418	    }
419	  else
420	    {
421	      *run = 0;
422	    }
423	  return *run >= DOUBAO_VAD_ON_FRAMES;
424	}
