429	static void log_service_error(const doubao_packet_t *packet,
430	                              const voice_transport_t *transport)
431	{
432	  char payload[257];
433	  size_t length, i;
434	
435	  length = packet->payload_size < sizeof(payload) - 1 ?
436	           packet->payload_size : sizeof(payload) - 1;
437	  for (i = 0; i < length; i++)
438	    {
439	      uint8_t v = packet->payload[i];
440	      payload[i] = v >= 0x20 && v <= 0x7e ? (char)v : '.';
441	    }
442	  payload[length] = '\0';
443	  fprintf(stderr, "doubao: service error event=%d code=%d logid=%s payload=%s\n",
444	          packet->event, packet->error_code,
445	          voice_transport_logid(transport), payload);
446	}
