448	/* 灯光开关标志,定义在 main.c;UI 灯光弹窗打开时据此回显开关状态。
449	 * 仅在此处读写该 bool,不触碰 LVGL 对象(worker 线程非 LVGL 上下文)。 */
450	extern bool g_led_is_on;
451	
452	/* 手电筒独占标志,定义在 main.c。为真时 claude_mqtt 的状态灯轮询不抢占 LED,
453	 * 否则手电筒点亮后会被状态灯周期性熄灭(表现为"亮一下就灭")。 */
454	extern bool g_flashlight_override;
455	
456	/*-----------------------------------------------------------------------
457	 * 语音意图:板载手电筒(WS2812 /dev/leds0)开关
458	 *
459	 * 从 ASR 识别原文里匹配 "手电筒/灯" + "打开/关闭",直接驱动板载 LED。
460	 * 运行在 session_loop(worker)线程:led_* 内部只是 open/write /dev/leds0
461	 * 的文件操作,线程安全;同步 g_led_is_on 供 UI 下次开窗回显,但不直接
462	 * 操作 light_switch 等 LVGL 控件(那不是线程安全的)。
463	 *
464	 * 返回 true 表示已命中并处理(命中后仍保留正常对话流,由豆包 TTS 口头
465	 * 确认);返回 false 表示非灯控意图,交给大模型正常应答。
466	 *---------------------------------------------------------------------*/
467	/* 空调红外学习去抖: two-pass ASR 会把"学习空调红外"重复回传十几帧,若每帧
468	 * 都起线程会并发读 /dev/lirc0、串口输出严重交织。用该标志保证只抓一次。 */
469	static volatile bool s_ac_learning = false;
470	
471	/* 红外学习进行中标志: 为真时 doubao_voice_start() 拒绝启动会话(挡住 face_detect
472	 * 等把音频拉回), 使采集窗口安静, 避免 CPU 抢占导致接收 FIFO 丢样。
473	 * 注: wakeup 线程原本也据此让出麦克风, 但该暂停已按需求暂时移除 —— 下次要
474	 * 学习红外时, 需在 wakeup.c 主循环重新加回 g_ir_learning 判空让麦, 否则唤醒
475	 * 麦克风采集的音频负载仍会污染抓帧。 */
476	volatile bool g_ir_learning = false;
477	
478	/* 本次学习输出的数组名: "学习开/关空调"分别抓开机帧/关机帧。仅在 s_ac_learning
479	 * 为真期间(单次学习)读写, 无并发。 */
480	static const char *s_ac_learn_label = "g_ac_frame_power_on";
481	
482	/* 空调红外抓帧线程:先停掉当前豆包会话并暂停唤醒,让系统安静下来再采集,
483	 * 否则并发音频负载会把每次采集都丢样毁掉(实测)。 */
484	static void *ac_ir_learn_thread(void *arg)
485	{
486	  (void)arg;
487	
488	  g_ir_learning = true;      /* 挡住会话重启(见 doubao_voice_start) */
489	  doubao_voice_stop();       /* 结束当前会话,释放音频/网络负载 */
490	  usleep(700 * 1000);        /* 等音频线程与 DMA 真正停下、FIFO 静默 */
491	
492	  ac_ir_learn_dump(s_ac_learn_label, 10000);
493	
494	  g_ir_learning = false;     /* 恢复 */
495	  s_ac_learning = false;
496	  return NULL;
497	}
498	
499	/* 空调开关状态,用于按状态翻转去抖(two-pass ASR 会重复回同一句)。
500	 * 初值 false 假设上电时空调为关;首条明确指令应为"打开空调"。 */
501	/* AC 指令时间去抖: two-pass ASR 会把同一句"打开空调"重复回传十几帧, 需去重;
502	 * 但不同次的命令(如没生效再喊一遍)必须允许重发。故按"同方向指令 N 毫秒内
503	 * 视为同一句而跳过"来去抖, 而非按开关状态(否则空调没真正开时再喊会被永久挡)。 */
504	#define AC_INTENT_COOLDOWN_MS 3000
505	static uint64_t s_ac_last_ms = 0;
506	static int      s_ac_last_dir = 0;   /* +1=开, -1=关, 0=无 */
507	
508	static bool voice_intent_handle(const char *text)
509	{
510	  if (text == NULL || text[0] == '\0')
511	    {
512	      return false;
513	    }
514	
515	  /* 学习触发词:说"学习空调/学习开空调"抓开机帧,"学习关空调"抓关机帧。
516	   * 抓到的数组打印到串口日志(见 ac_ir_learn_dump), 需含"学习"+"空调"。
517	   * 放在开/关控制分支之前, 否则"学习关空调"里的"关空调"会被当成关机指令。 */
518	  if (strstr(text, "学习") != NULL && strstr(text, "空调") != NULL)
519	    {
520	      /* 去抖:已有一次学习在进行则忽略后续重复帧。 */
521	      if (!s_ac_learning)
522	        {
523	          pthread_t tid;
524	          pthread_attr_t attr;
525	
526	          /* 含"关"(关/关闭)→ 抓关机帧, 否则抓开机帧。 */
527	          s_ac_learn_label = (strstr(text, "关") != NULL)
528	                             ? "g_ac_frame_power_off"
529	                             : "g_ac_frame_power_on";
530	          s_ac_learning = true;
531	          pthread_attr_init(&attr);
532	          pthread_attr_setstacksize(&attr, 8192);
533	          if (pthread_create(&tid, &attr, ac_ir_learn_thread, NULL) == 0)
534	            {
535	              pthread_detach(tid);
536	              DOUBAO_LOG("voice intent: AC IR learn started -> %s (\"%s\")",
537	                         s_ac_learn_label, text);
538	            }
539	          else
540	            {
541	              s_ac_learning = false;  /* 起线程失败,允许重试 */
542	            }
543	          pthread_attr_destroy(&attr);
544	        }
545	      return true;
546	    }
547	
548	  /* 空调红外意图:命中"空调" + 明确的开/关,直接驱动红外发射。放在灯控
549	   * 触发词判断之前,因为"空调"不含"灯/手电筒"会被下面的 guard 提前放行。 */
550	  if (strstr(text, "空调") != NULL)
551	    {
552	      bool ac_on  = strstr(text, "打开") || strstr(text, "开启") ||
553	                    strstr(text, "开一下") || strstr(text, "开空调");
554	      bool ac_off = strstr(text, "关闭") || strstr(text, "关掉") ||
555	                    strstr(text, "关一下") || strstr(text, "关空调");
556	
557	      if (ac_on != ac_off)   /* 仅在明确单向指令时动作 */
558	        {
559	          int dir = ac_on ? 1 : -1;
560	          uint64_t now = now_ms();
561	
562	          /* 同方向指令且在冷却期内 → 判为同一句的重复帧, 跳过。
563	           * 超出冷却期(或换方向)则重新发送 —— 支持"没生效再喊一遍"。 */
564	          if (dir == s_ac_last_dir &&
565	              (now - s_ac_last_ms) < AC_INTENT_COOLDOWN_MS)
566	            {
567	              return true;
568	            }
569	
570	          s_ac_last_dir = dir;
571	          s_ac_last_ms = now;
572	
573	          if (ac_on)
574	            {
575	              DOUBAO_LOG("voice intent: AC ON (\"%s\")", text);
576	              ac_ir_power_on();
577	            }
578	          else
579	            {
580	              DOUBAO_LOG("voice intent: AC OFF (\"%s\")", text);
581	              ac_ir_power_off();
582	            }
583	          return true;
584	        }
585	    }
586	
587	  /* 触发词:显式"手电筒",或口语化的"开灯/关灯"里的"灯"。 */
588	  if (strstr(text, "手电筒") == NULL && strstr(text, "灯") == NULL)
589	    {
590	      return false;
591	    }
592	
593	  bool want_on  = strstr(text, "打开") || strstr(text, "开启") ||
594	                  strstr(text, "开一下") || strstr(text, "开灯");
595	  bool want_off = strstr(text, "关闭") || strstr(text, "关掉") ||
596	                  strstr(text, "关一下") || strstr(text, "关灯");
597	
598	  /* 同时命中或都没命中(如只说"手电筒") → 非明确指令,交给大模型。 */
599	  if (want_on == want_off)
600	    {
601	      return false;
602	    }
603	
604	  /* two-pass ASR 会把同一句流式返回十几次,若每帧都驱动 WS2812 会造成
605	   * 反复重写、肉眼可见的闪烁。这里只在"目标状态与当前状态不同"时才动
606	   * 硬件,即按状态翻转去抖:重复的相同指令直接跳过。 */
607	  if (want_on)
608	    {
609	      if (!g_led_is_on)
610	        {
611	          led_controller_init();          /* 幂等,重复调用无副作用 */
612	          led_set_color(LED_COLOR_WHITE); /* 手电筒:白光最亮 */
613	          led_set_brightness(100);
614	          g_led_is_on = true;
615	          g_flashlight_override = true;   /* 抢占 LED,状态灯让位 */
616	          led_on();
617	          DOUBAO_LOG("voice intent: flashlight ON (\"%s\")", text);
618	        }
619	    }
620	  else
621	    {
622	      if (g_led_is_on)
623	        {
624	          g_led_is_on = false;
625	          g_flashlight_override = false;  /* 归还 LED 给状态灯 */
626	          led_off();
627	          DOUBAO_LOG("voice intent: flashlight OFF (\"%s\")", text);
628	        }
629	    }
630	
631	  return true;
632	}
633	
634	/* 处理一帧服务端数据。turn_open:本轮是否已开(用户话首开新轮);
635	 * chat_ended:文字回复完;tts_ended:359 本轮 TTS 全部发完;
636	 * last_audio_ms:最近 TTS 音频时刻;discard:挂断后丢弃残留 TTS。 */
637	static void handle_fd(const doubao_packet_t *packet,
638	                      const voice_transport_t *transport,
639	                      voice_player_t **player, bool *turn_open,
640	                      bool *chat_ended, uint64_t *last_audio_ms,
641	                      bool *discard, bool *tts_ended)
642	{
643	  char text[DOUBAO_REPLY_MAX];
644	
645	  if (packet->kind == DOUBAO_PACKET_ERROR)
646	    {
647	      log_service_error(packet, transport);
648	      /* 会话中的 service error(如 DialogAudioIdleTimeout)可恢复,交由上层
649	       * 重连,不置 UI ERROR 避免闪屏。 */
650	      return;
651	    }
652	
653	  if (packet->kind == DOUBAO_PACKET_AUDIO)
654	    {
655	      if (*discard)
656	        {
657	          return;
658	        }
659	      if (g_voice.config.tts_enabled && !*player)
660	        {
661	          if (voice_player_open(player, g_voice.config.playback_device,
662	                                DOUBAO_TTS_RATE, DOUBAO_TTS_CHANNELS,
663	                                DOUBAO_TTS_BITS) == 0)
664	            {
665	              set_state(DOUBAO_VOICE_PLAYING, NULL);
666	            }
667	        }
668	      if (*player)
669	        {
670	          (void)voice_player_write(*player, packet->payload,
671	                                   packet->payload_size);
672	        }
673	      *last_audio_ms = now_ms();
674	      return;
675	    }
676	
677	  if (packet->kind != DOUBAO_PACKET_JSON)
678	    {
679	      return;
680	    }
681	
682	  /* 用户话首 → 开新一轮 */
683	  if ((packet->event == DOUBAO_EVENT_ASR_START ||
684	       packet->event == DOUBAO_EVENT_ASR_RESPONSE) && !*turn_open)
685	    {
686	      begin_turn_snapshot();
687	      *turn_open = true;
688	      *chat_ended = false;
689	      if (tts_ended)
690	        {
691	          *tts_ended = false;
692	        }
693	      set_state(DOUBAO_VOICE_RECORDING, NULL);
694	    }
695	
696	  if (packet->event == DOUBAO_EVENT_ASR_RESPONSE)
697	    {
698	      if (doubao_protocol_get_text(packet->payload, packet->payload_size,
699	                                   "text", text, sizeof(text)))
700	        {
701	          /* 诊断:确认 ASR 识别原文与意图匹配结果。 */
702	          DOUBAO_LOG("ASR text=[%s]", text);
703	
704	          pthread_mutex_lock(&g_voice.mutex);
705	          copy_text(g_voice.snapshot.user_text,
706	                    sizeof(g_voice.snapshot.user_text), text);
707	          pthread_mutex_unlock(&g_voice.mutex);
708	
709	          /* 灯控意图:命中"打开/关闭手电筒"直接驱动板载 LED。
710	           * ASR two-pass 会多次回本轮识别文本,voice_intent_handle
