748	/*-----------------------------------------------------------------------
749	 * 建立会话:连接 + START_CONNECTION + START_SESSION + 等待确认
750	 *---------------------------------------------------------------------*/
751	static int establish_session(voice_transport_t **out, char *session_id,
752	                             size_t session_id_size)
753	{
754	  voice_transport_t *transport = NULL;
755	  voice_transport_config_t tcfg;
756	  char connect_id[48];
757	  char start_session_json[1024];
758	  int ret = -EIO;
759	
760	  make_identifier(session_id, session_id_size, "vela-session");
761	  make_identifier(connect_id, sizeof(connect_id), "vela-connect");
762	  memset(&tcfg, 0, sizeof(tcfg));
763	  tcfg.url = DOUBAO_WS_URL;
764	  tcfg.app_id = g_voice.config.app_id;
765	  tcfg.access_token = g_voice.config.access_token;
766	  tcfg.resource_id = g_voice.config.resource_id;
767	  tcfg.app_key = g_voice.config.app_key;
768	  tcfg.connect_id = connect_id;
769	
770	  for (int attempt = 1; attempt <= 3 && !is_shutdown(); attempt++)
771	    {
772	      ret = voice_transport_connect(&transport, &tcfg, DOUBAO_CONNECT_TIMEOUT_MS);
773	      if (ret == 0)
774	        {
775	          break;
776	        }
777	      if (attempt < 3)
778	        {
779	          usleep(300 * 1000);
780	        }
781	    }
782	  if (ret < 0)
783	    {
784	      return ret;
785	    }
786	  DOUBAO_LOG("connected, logid=%s", voice_transport_logid(transport));
787	
788	  build_start_session_json(start_session_json, sizeof(start_session_json));
789	
790	  if (send_json(transport, DOUBAO_EVENT_START_CONNECTION, session_id, "{}") < 0 ||
791	      send_json(transport, DOUBAO_EVENT_START_SESSION, session_id,
792	                start_session_json) < 0)
793	    {
794	      voice_transport_close(transport);
795	      return -EIO;
796	    }
797	
798	  /* 等待 CONNECTION_STARTED(50) + SESSION_STARTED(150)。64KB 接收缓冲堆分配,
799	   * 避免与 send_json 的大 frame 叠加顶高建连路径栈峰值。 */
800	  {
801	    uint8_t *buf = malloc(DOUBAO_WS_BUFFER_SIZE);
802	    voice_ws_opcode_t op;
803	    doubao_packet_t pkt;
804	    bool conn_ok = false, sess_ok = false;
805	    int tries = 0;
806	
807	    if (!buf)
808	      {
809	        voice_transport_close(transport);
810	        return -ENOMEM;
811	      }
812	    while ((!conn_ok || !sess_ok) && tries < 50 && !is_shutdown())
813	      {
814	        ret = voice_transport_receive(transport, &op, buf,
815	                                      DOUBAO_WS_BUFFER_SIZE, 5000);
816	        if (ret <= 0 || op != VOICE_WS_BINARY)
817	          {
818	            usleep(50000);
819	            tries++;
820	            continue;
821	          }
822	        if (doubao_protocol_decode(buf, (size_t)ret, &pkt) < 0)
823	          {
824	            usleep(50000);
825	            tries++;
826	            continue;
827	          }
828	        if (pkt.event == DOUBAO_EVENT_CONNECTION_STARTED)
829	          {
830	            conn_ok = true;
831	          }
832	        if (pkt.event == DOUBAO_EVENT_SESSION_STARTED)
833	          {
834	            sess_ok = true;
835	          }
836	        tries++;
837	      }
838	    free(buf);
839	    if (!sess_ok)
840	      {
841	        voice_transport_close(transport);
842	        return -EIO;
843	      }
844	  }
845	  DOUBAO_LOG("session started");
846	  *out = transport;
847	  return 0;
848	}
