850	/*-----------------------------------------------------------------------
851	 * 全双工会话主循环
852	 *---------------------------------------------------------------------*/
853	static int session_loop(voice_transport_t *transport, const char *session_id)
854	{
855	  voice_capture_t *capture = NULL;
856	  voice_player_t *player = NULL;
857	  uint8_t audio[DOUBAO_CAPTURE_PACKET_BYTES];
858	  const uint8_t silence[DOUBAO_CAPTURE_PACKET_BYTES] = {0};
859	  uint8_t received[DOUBAO_WS_BUFFER_SIZE];
860	  voice_ws_opcode_t opcode;
861	  doubao_packet_t packet;
862	  bool turn_open = false;
863	  bool chat_ended = false;
864	  bool tts_ended = false;
865	  uint64_t playback_end_ms = 0;
866	  bool discard_turn_audio = false;
867	  uint64_t last_audio_ms = 0;
868	  unsigned vad_run = 0;
869	  bool was_talking = false;
870	  int ret;
871	
872	  set_state(is_talking() ? DOUBAO_VOICE_CONNECTING : DOUBAO_VOICE_IDLE, NULL);
873	  DOUBAO_LOG("full-duplex connection established, standing by");
874	
875	  while (!is_shutdown())
876	    {
877	      bool talking = is_talking();
878	
879	      /* 用户暂停:停止全双工,保留连接 */
880	      if (take_stop_playback())
881	        {
882	          if (player) { voice_player_abort(player); player = NULL; }
883	          if (capture) { voice_capture_close(capture); capture = NULL; }
884	          turn_open = false;
885	          chat_ended = false;
886	          discard_turn_audio = true;
887	          set_state(DOUBAO_VOICE_IDLE, NULL);
888	        }
889	
890	      /* 音乐抢占:立即停播、丢弃残留 TTS、回 IDLE */
891	      if (take_abort_playback())
892	        {
893	          if (player) { voice_player_abort(player); player = NULL; }
894	          turn_open = false;
895	          chat_ended = false;
896	          discard_turn_audio = true;
897	          set_state(is_talking() ? DOUBAO_VOICE_LISTENING
898	                                 : DOUBAO_VOICE_IDLE, NULL);
899	        }
900	
901	      /* 对话开始/停止边沿 */
902	      if (talking && !was_talking)
903	        {
904	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_WAKEUP
905	          /* 开麦前等唤醒线程释放麦克风(它每圈轮询 talking, 看到即停,
906	           * 正常交接 ~200ms)。超时兜底: 唤醒线程卡死时放弃等待强开,
907	           * 否则会话永远起不来。 */
908	          {
909	            uint64_t wait_start = now_ms();
910	            while (wakeup_is_recording() && !is_shutdown() &&
911	                   now_ms() - wait_start < DOUBAO_MIC_HANDOFF_TIMEOUT_MS)
912	              {
913	                usleep(20 * 1000);
914	              }
915	            if (wakeup_is_recording())
916	              {
917	                DOUBAO_LOG("mic handoff: wakeup still recording after %dms, "
918	                           "opening anyway", DOUBAO_MIC_HANDOFF_TIMEOUT_MS);
919	              }
920	            else if (now_ms() - wait_start >= 20)
921	              {
922	                DOUBAO_LOG("mic handoff: waited %llums for wakeup release",
923	                           (unsigned long long)(now_ms() - wait_start));
924	              }
925	          }
926	#endif
927	          ret = voice_capture_open(&capture, g_voice.config.capture_device,
928	                                   DOUBAO_CAPTURE_RATE, DOUBAO_CAPTURE_CHANNELS,
929	                                   DOUBAO_CAPTURE_BITS);
930	          if (ret < 0)
931	            {
932	              set_state(DOUBAO_VOICE_ERROR, "麦克风不可用");
933	              return RC_STOP;
934	            }
935	          discard_turn_audio = false;
936	          set_state(DOUBAO_VOICE_LISTENING, NULL);
937	          DOUBAO_LOG("talk START: capture opened, LISTENING");
938	        }
939	      else if (!talking && was_talking)
940	        {
941	          if (player) { voice_player_abort(player); player = NULL; }
942	          if (capture) { voice_capture_close(capture); capture = NULL; }
943	          turn_open = false;
944	          chat_ended = false;
945	          vad_run = 0;
946	          discard_turn_audio = true;
947	          set_state(DOUBAO_VOICE_IDLE, NULL);
948	        }
949	      was_talking = talking;
950	
951	      /* 文字问答受理:仅待命(非对话)且无回复在播时取一条 pending query */
952	      if (!talking && !player)
953	        {
954	          char q[DOUBAO_TEXT_MAX];
955	          bool have = false;
956	          pthread_mutex_lock(&g_voice.mutex);
957	          if (g_voice.query_pending)
958	            {
959	              copy_text(q, sizeof(q), g_voice.pending_query);
960	              g_voice.query_pending = false;
961	              have = true;
962	            }
963	          pthread_mutex_unlock(&g_voice.mutex);
964	          if (have)
965	            {
966	              begin_turn_snapshot();
967	              discard_turn_audio = false;
968	              pthread_mutex_lock(&g_voice.mutex);
969	              copy_text(g_voice.snapshot.user_text,
970	                        sizeof(g_voice.snapshot.user_text), q);
971	              pthread_mutex_unlock(&g_voice.mutex);
972	              set_state(DOUBAO_VOICE_WAITING_RESPONSE, NULL);
973	              DOUBAO_LOG("text query: %s", q);
974	              if (send_text_query(transport, session_id, q) < 0)
975	                {
976	                  return RC_RECONNECT;
977	                }
978	            }
979	        }
980	
981	      /* (A) 采集一包(非阻塞,~20ms 节拍源) */
982	      if (!capture)
983	        {
984	          if (send_audio(transport, session_id, silence, sizeof(silence)) < 0)
985	            {
986	              return RC_RECONNECT;
987	            }
988	          usleep(DOUBAO_CAPTURE_PACKET_MS * 1000);
989	          ret = -EAGAIN;
990	        }
991	      else
992	        {
993	          ret = voice_capture_read_packet(capture, audio, sizeof(audio));
994	        }
995	      if (ret == (int)sizeof(audio))
996	        {
997	          bool playing = (player != NULL);
998	          if (talking && playing && DOUBAO_BARGE_IN_ENABLED &&
999	              energy_vad(audio, sizeof(audio), &vad_run))
1000	            {
1001	              voice_player_abort(player);
1002	              player = NULL;
1003	              playing = false;
1004	              chat_ended = false;
1005	              vad_run = 0;
1006	              set_state(DOUBAO_VOICE_LISTENING, NULL);
1007	            }
1008	          /* 上传源:待命/播放中/播完静音门内 → 静音帧;对话中且门已过 → 真音频 */
1009	          bool post_tts_muted = playback_end_ms != 0 &&
1010	              (now_ms() - playback_end_ms < DOUBAO_POST_TTS_MUTE_MS);
1011	          const uint8_t *up = (talking && !playing && !post_tts_muted)
1012	                              ? audio : silence;
1013	          /* 诊断:统计真实音频上传帧数(每 50 帧≈1s 打一次)。 */
1014	          if (up == audio)
1015	            {
1016	              static unsigned mic_frames;
1017	              if (++mic_frames % 50 == 0)
1018	                {
1019	                  DOUBAO_LOG("uploading mic audio, frames=%u energy=%u",
1020	                             mic_frames, frame_energy(audio, sizeof(audio)));
1021	                }
1022	            }
1023	          if (send_audio(transport, session_id, up, sizeof(audio)) < 0)
1024	            {
1025	              if (player) voice_player_close(player);
1026	              voice_capture_close(capture);
1027	              return RC_RECONNECT;
1028	            }
1029	        }
1030	      else if (ret == -EAGAIN)
1031	        {
1032	          /* 无新采集数据,继续排空接收 */
1033	        }
1034	      else
1035	        {
1036	          if (player) voice_player_close(player);
1037	          voice_capture_close(capture);
1038	          set_state(DOUBAO_VOICE_ERROR, "语音采集异常");
1039	          return RC_STOP;
1040	        }
1041	
1042	      /* (B) 排空当前可读服务端帧(非阻塞) */
1043	      for (;;)
1044	        {
1045	          /* AI 说话中被挂断:立即中止播放、丢弃残留 TTS 并跳出 */
1046	          if (player && was_talking && !is_talking())
1047	            {
1048	              voice_player_abort(player);
1049	              player = NULL;
1050	              discard_turn_audio = true;
1051	              break;
1052	            }
1053	          ret = voice_transport_receive(transport, &opcode, received,
1054	                                        sizeof(received), 0);
1055	          if (ret == 0)
1056	            {
1057	              break;
1058	            }
1059	          if (ret < 0)
1060	            {
1061	              if (player) voice_player_close(player);
1062	              voice_capture_close(capture);
1063	              return RC_RECONNECT;
1064	            }
1065	          if (opcode != VOICE_WS_BINARY)
1066	            {
1067	              continue;
1068	            }
1069	          if (doubao_protocol_decode(received, (size_t)ret, &packet) < 0)
1070	            {
1071	              continue;
1072	            }
1073	          if (packet.kind != DOUBAO_PACKET_AUDIO)
1074	            {
1075	              DOUBAO_LOG("rx event=%d kind=%d payload=%zu", packet.event,
1076	                         packet.kind, packet.payload_size);
1077	            }
1078	          handle_fd(&packet, transport, &player, &turn_open, &chat_ended,
1079	                    &last_audio_ms, &discard_turn_audio, &tts_ended);
1080	          if (packet.kind == DOUBAO_PACKET_ERROR)
1081	            {
1082	              if (player) voice_player_close(player);
1083	              voice_capture_close(capture);
1084	              return RC_STOP;
1085	            }
1086	        }
1087	
1088	      /* (C) 播放排空窗口收尾 */
1089	      if (player &&
1090	          (tts_ended ||
1091	           (chat_ended && now_ms() - last_audio_ms > DOUBAO_DRAIN_TIMEOUT_MS)))
1092	        {
1093	          voice_player_close(player);
1094	          player = NULL;
1095	          chat_ended = false;
1096	          tts_ended = false;
1097	          playback_end_ms = now_ms();
1098	          set_state(is_talking() ? DOUBAO_VOICE_LISTENING
1099	                                 : DOUBAO_VOICE_IDLE, NULL);
1100	        }
1101	
1102	      /* 文字 query 兜底:回复结束却无 TTS,复位 IDLE 否则 ask_text 永久被拒 */
1103	      if (chat_ended && !player && !is_talking() &&
1104	          now_ms() - last_audio_ms > DOUBAO_DRAIN_TIMEOUT_MS)
1105	        {
1106	          chat_ended = false;
1107	          tts_ended = false;
1108	          turn_open = false;
1109	          set_state(DOUBAO_VOICE_IDLE, NULL);
1110	          DOUBAO_LOG("text-query turn done (no TTS), back to IDLE");
1111	        }
1112	    }
1113	
1114	  if (player) voice_player_close(player);
1115	  if (capture) voice_capture_close(capture);
1116	  return RC_STOP;
1117	}
1118	
1119	/*-----------------------------------------------------------------------
1120	 * 持久 worker
1121	 *---------------------------------------------------------------------*/
1122	static void *voice_worker(void *arg)
1123	{
1124	  voice_transport_t *transport = NULL;
1125	  char session_id[48] = {0};
1126	  bool connected = false;
1127	  bool first_connect = true;
1128	
1129	  (void)arg;
1130	
1131	  while (!is_shutdown())
1132	    {
1133	      if (!connected)
1134	        {
1135	          if (first_connect)
1136	            {
1137	              set_state(DOUBAO_VOICE_CONNECTING, NULL);
1138	            }
1139	          while (!wifi_status_is_connected() && !is_shutdown())
1140	            {
1141	              usleep(500 * 1000);
1142	            }
1143	          if (is_shutdown())
1144	            {
1145	              break;
1146	            }
1147	          if (establish_session(&transport, session_id,
1148	                                sizeof(session_id)) == 0)
1149	            {
1150	              connected = true;
1151	              first_connect = false;
1152	              set_state(DOUBAO_VOICE_IDLE, NULL);
1153	            }
1154	          else
1155	            {
1156	              if (is_shutdown())
1157	                {
1158	                  break;
1159	                }
1160	              if (first_connect)
1161	                {
1162	                  set_state(DOUBAO_VOICE_ERROR, "无法连接豆包服务");
1163	                }
1164	              usleep(1000 * 1000);
1165	              continue;
1166	            }
1167	        }
1168	
1169	      if (session_loop(transport, session_id) == RC_RECONNECT)
1170	        {
1171	          voice_transport_close(transport);
1172	          transport = NULL;
1173	          connected = false;
1174	          continue;
1175	        }
1176	      /* RC_STOP:一般是致命采集/服务错误,关连接后重连 */
1177	      voice_transport_close(transport);
1178	      transport = NULL;
1179	      connected = false;
1180	    }
1181	
1182	  if (transport)
1183	    {
1184	      (void)send_json(transport, DOUBAO_EVENT_FINISH_SESSION, session_id, "{}");
1185	      (void)send_json(transport, DOUBAO_EVENT_FINISH_CONNECTION, session_id, "{}");
1186	      voice_transport_close(transport);
1187	    }
1188	
1189	  pthread_mutex_lock(&g_voice.mutex);
1190	  g_voice.worker_running = false;
1191	  pthread_mutex_unlock(&g_voice.mutex);
1192	  return NULL;
1193	}
1194	
1195	/*-----------------------------------------------------------------------
1196	 * public API
1197	 *---------------------------------------------------------------------*/
1198	int doubao_voice_init(void)
1199	{
1200	  int ret;
1201	
1202	  memset(&g_voice, 0, sizeof(g_voice));
1203	  pthread_mutex_init(&g_voice.mutex, NULL);
1204	
1205	  g_voice.initialized = true;
1206	#if DOUBAO_SECRETS_AVAILABLE
1207	  g_voice.config.app_id = DOUBAO_APP_ID;
1208	  g_voice.config.access_token = DOUBAO_ACCESS_TOKEN;
1209	  g_voice.config.resource_id = DOUBAO_RESOURCE_ID;
1210	  g_voice.config.app_key = DOUBAO_APP_KEY;
1211	  g_voice.config.model = DOUBAO_MODEL;
1212	  g_voice.config.speaker = DOUBAO_SPEAKER;
1213	  g_voice.config.capture_device = CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_CAPTURE_DEV;
1214	  g_voice.config.playback_device = CONFIG_LVX_USE_DEMO_CONTEST2026_106_DOUBAO_PLAYBACK_DEV;
1215	  g_voice.config.tts_enabled = 1;
1216	  g_voice.snapshot.state = DOUBAO_VOICE_CONNECTING;
1217	#else
1218	  g_voice.snapshot.state = DOUBAO_VOICE_UNCONFIGURED;
1219	  return 0;
1220	#endif
1221	
1222	  if (!doubao_voice_is_configured())
1223	    {
1224	      g_voice.snapshot.state = DOUBAO_VOICE_UNCONFIGURED;
1225	      return 0;
1226	    }
1227	
1228	  load_dialog_id();
1229	
1230	  {
1231	    pthread_attr_t attr;
1232	    pthread_attr_init(&attr);
1233	    /* 栈 8MB:session_loop 内 received[64KB] + send_json frame[66KB] + nxaudio/
1234	     * curl+TLS 深调用叠加,断网重连路径峰值很高。Hexfight 实测需 8MB 防爆栈。 */
1235	    pthread_attr_setstacksize(&attr, 8 * 1024 * 1024);
1236	    g_voice.worker_running = true;
1237	    ret = pthread_create(&g_voice.worker, &attr, voice_worker, NULL);
1238	    pthread_attr_destroy(&attr);
1239	  }
1240	  if (ret != 0)
1241	    {
1242	      g_voice.worker_running = false;
1243	      set_state(DOUBAO_VOICE_ERROR, "worker 启动失败");
1244	      return -ret;
1245	    }
1246	  return 0;
1247	}
1248	
1249	void doubao_voice_deinit(void)
1250	{
1251	  bool join = false;
1252	
1253	  if (!g_voice.initialized)
1254	    {
1255	      return;
1256	    }
1257	
1258	  pthread_mutex_lock(&g_voice.mutex);
1259	  g_voice.shutdown = true;
1260	  g_voice.talking = false;
1261	  join = g_voice.worker_running;
1262	  pthread_mutex_unlock(&g_voice.mutex);
1263	
