1	/****************************************************************************
2	 * app/home_scense/doubao/doubao_voice.c
3	 * Full-duplex continuous-conversation coordinator for Doubao RealtimeAPI.
4	 *
5	 * "开始会话" 后 session_loop 单线程内交替执行 [非阻塞采集上传] +
6	 * [非阻塞排空接收 ASR/Chat/TTS] + [播放],服务端 VAD 自动断句,多轮连续
7	 * 问答,直到 "停止会话"。连接常驻(worker 持有),待命期发静音帧保活,
8	 * 掉线自动重连。文字问答(ChatTextQuery=501)在待命态复用同一连接。
9	 *
10	 * 外放喇叭无硬件 AEC:AI 播放期间门控麦克风上传(改上传静音帧)以根治
11	 * 自问自答自循环;播完后再压制 POST_TTS_MUTE_MS 盖住残响窗口。
12	 *
13	 * 并发模型为单线程交替:transport 基于单个 curl 句柄,send/recv 不能并发;
14	 * 采集侧 ~20ms 节拍驱动,receive 用 timeout=0 非阻塞排空。
15	 *
16	 * NuttX adaptation — nxaudio 采集/播放,pthread worker,mutex 保护 snapshot。
17	 ****************************************************************************/
18	
19	#include "doubao_voice.h"
20	#include "doubao_protocol.h"
21	#include "voice_capture.h"
22	#include "voice_player.h"
23	#include "voice_transport.h"
24	#include "../wifi_status.h"
25	#include "../led_control.h"
