325	/* 把 src 转义为合法 JSON 字符串内容(不含外层引号)写入 dst。 */
326	static void json_escape(char *dst, size_t dst_size, const char *src)
327	{
328	  size_t o = 0;
329	  if (!dst || dst_size == 0)
330	    {
331	      return;
332	    }
333	  for (const char *p = src ? src : ""; *p && o + 2 < dst_size; p++)
334	    {
335	      unsigned char c = (unsigned char)*p;
336	      switch (c)
337	        {
338	          case '"':  dst[o++] = '\\'; dst[o++] = '"'; break;
339	          case '\\': dst[o++] = '\\'; dst[o++] = '\\'; break;
340	          case '\n': dst[o++] = '\\'; dst[o++] = 'n'; break;
341	          case '\r': dst[o++] = '\\'; dst[o++] = 'r'; break;
342	          case '\t': dst[o++] = '\\'; dst[o++] = 't'; break;
343	          default:
344	            if (c < 0x20)
345	              {
346	                if (o + 6 < dst_size)
347	                  {
348	                    static const char hex[] = "0123456789abcdef";
349	                    dst[o++] = '\\'; dst[o++] = 'u'; dst[o++] = '0'; dst[o++] = '0';
350	                    dst[o++] = hex[(c >> 4) & 0xf]; dst[o++] = hex[c & 0xf];
351	                  }
352	              }
353	            else
354	              {
355	                dst[o++] = (char)c;
356	              }
357	        }
358	    }
359	  dst[o] = '\0';
360	}
