/* 20ms 帧内 |sample| 均值,用于 barge-in VAD 与回声标定。 */
static unsigned frame_energy(const uint8_t *frame, size_t size)
{
  const int16_t *s = (const int16_t *)frame;
  size_t n = size / 2;
  uint64_t sum = 0;

  if (n == 0)
    {
      return 0;
    }
  for (size_t i = 0; i < n; i++)
    {
      int v = s[i];
      sum += (uint64_t)(v < 0 ? -v : v);
    }
  return (unsigned)(sum / n);
}

