782	  char start_session_json[1024];
783	  int ret = -EIO;
784	
785	  make_identifier(session_id, session_id_size, "vela-session");
786	  make_identifier(connect_id, sizeof(connect_id), "vela-connect");
787	  memset(&tcfg, 0, sizeof(tcfg));
