792	  tcfg.app_key = g_voice.config.app_key;
793	  tcfg.connect_id = connect_id;
794	
795	  for (int attempt = 1; attempt <= 3 && !is_shutdown(); attempt++)
796	    {
797	      ret = voice_transport_connect(&transport, &tcfg, DOUBAO_CONNECT_TIMEOUT_MS);
798	      if (ret == 0)
799	        {
800	          break;
801	        }
802	      if (attempt < 3)
803	        {
804	          usleep(300 * 1000);
805	        }
806	    }
807	  if (ret < 0)
808	    {
809	      return ret;
810	    }
811	  DOUBAO_LOG("connected, logid=%s", voice_transport_logid(transport));
812	
813	  build_start_session_json(start_session_json, sizeof(start_session_json));
814	
815	  if (send_json(transport, DOUBAO_EVENT_START_CONNECTION, session_id, "{}") < 0 ||
816	      send_json(transport, DOUBAO_EVENT_START_SESSION, session_id,
817	                start_session_json) < 0)
818	    {
819	      voice_transport_close(transport);
820	      return -EIO;
821	    }
822	
823	  /* 等待 CONNECTION_STARTED(50) + SESSION_STARTED(150)。64KB 接收缓冲堆分配,
824	   * 避免与 send_json 的大 frame 叠加顶高建连路径栈峰值。 */
825	  {
826	    uint8_t *buf = malloc(DOUBAO_WS_BUFFER_SIZE);
827	    voice_ws_opcode_t op;
828	    doubao_packet_t pkt;
829	    bool conn_ok = false, sess_ok = false;
830	    int tries = 0;
831	
832	    if (!buf)
833	      {
834	        voice_transport_close(transport);
835	        return -ENOMEM;
836	      }
837	    while ((!conn_ok || !sess_ok) && tries < 50 && !is_shutdown())
838	      {
839	        ret = voice_transport_receive(transport, &op, buf,
840	                                      DOUBAO_WS_BUFFER_SIZE, 5000);
841	        if (ret <= 0 || op != VOICE_WS_BINARY)
842	          {
843	            usleep(50000);
844	            tries++;
845	            continue;
846	          }
847	        if (doubao_protocol_decode(buf, (size_t)ret, &pkt) < 0)
848	          {
849	            usleep(50000);
850	            tries++;
851	            continue;
852	          }
853	        if (pkt.event == DOUBAO_EVENT_CONNECTION_STARTED)
854	          {
855	            conn_ok = true;
856	          }
857	        if (pkt.event == DOUBAO_EVENT_SESSION_STARTED)
858	          {
859	            sess_ok = true;
860	          }
861	        tries++;
862	      }
863	    free(buf);
864	    if (!sess_ok)
865	      {
866	        voice_transport_close(transport);
867	        return -EIO;
868	      }
869	  }
870	  DOUBAO_LOG("session started");
871	  *out = transport;
872	  return 0;
873	}
