136	   * 供上层区分"暂时没数据"(继续等)与"真错误"。 */
137	  r=recv_exact(c,fd,hd,2,ms);
138	  if(r==0)return-ETIMEDOUT;
139	  if(r==-ECONNRESET)return-ECONNRESET;   /* 连接已死 → 上层重连 */
140	  if(r!=2)return-EIO;
141	  op=hd[0]&0x0f;ln=hd[1]&0x7f;if(hd[1]&WS_MASK)return-EIO;
142	  if(ln==126){uint8_t e[2];if(recv_exact(c,fd,e,2,5000)!=2)return-EIO;
143	    ln=((uint64_t)e[0]<<8)|e[1];}
144	  else if(ln==127){uint8_t e[8];uint32_t hi,lo;
145	    if(recv_exact(c,fd,e,8,5000)!=8)return-EIO;
146	    hi=((uint32_t)e[0]<<24)|((uint32_t)e[1]<<16)|((uint32_t)e[2]<<8)|e[3];
147	    lo=((uint32_t)e[4]<<24)|((uint32_t)e[5]<<16)|((uint32_t)e[6]<<8)|e[7];
148	    ln=(uint64_t)hi*0x100000000u+lo;}
149	  if(ln>cap)return-EMSGSIZE;
150	  if(ln>0){r=recv_exact(c,fd,p,(size_t)ln,5000);if(r!=(int)ln)return-EIO;}
151	  ps=(size_t)ln;
152	  switch(op){case WS_OPCODE_CLOSE:{
153	    /* 记录服务端关连接的状态码(payload 前 2 字节大端),定位为何频繁断开 */
154	    int code = (ln>=2)? (((int)p[0]<<8)|p[1]) : -1;
155	    DOUBAO_ERR("doubao:WS CLOSE code=%d len=%llu",code,(unsigned long long)ln);
156	    return-ECONNRESET;}
157	  case WS_OPCODE_PING:{
158	    /* WebSocket 要求客户端→服务端所有帧必须加掩码,并回显 PING 的
159	     * payload。此前回的 PONG 未加掩码(且丢了 payload),服务器判定协议
160	     * 违规 → 每隔几秒关连接,表现为豆包反复重连。这里用带掩码的 ws_send
161	     * 发 PONG(ws_send 内部已加掩码位+4字节掩码 key)。 */
162	    uint8_t mp[2]={WS_FIN|WS_OPCODE_PONG,WS_MASK}; uint8_t mk[4]; size_t i;
163	    uint8_t *fr; size_t frn;
164	    if(ln>125)return 0;                    /* 控制帧 payload ≤125,超出忽略 */
165	    mp[1]|=(uint8_t)ln;
166	    frn=2+4+(size_t)ln; fr=malloc(frn);
167	    if(!fr)return 0;
168	    fr[0]=mp[0]; fr[1]=mp[1];
169	    mk[0]=(uint8_t)(rand()&0xff);mk[1]=(uint8_t)(rand()&0xff);
170	    mk[2]=(uint8_t)(rand()&0xff);mk[3]=(uint8_t)(rand()&0xff);
171	    memcpy(fr+2,mk,4);
172	    for(i=0;i<(size_t)ln;i++)fr[6+i]=p[i]^mk[i&3];  /* 回显 PING payload */
173	    curl_send_to(c,fd,fr,frn,2000);
174	    free(fr);
175	    return 0;}
176	  case WS_OPCODE_BINARY:return(int)ps;default:return(int)ps;}
177	}
