185	  curl_easy_setopt(t->curl,CURLOPT_CONNECT_ONLY,1L);
186	  curl_easy_setopt(t->curl,CURLOPT_CONNECTTIMEOUT_MS,(long)ms);
187	  curl_easy_setopt(t->curl,CURLOPT_SSL_VERIFYPEER,0L);
188	  curl_easy_setopt(t->curl,CURLOPT_SSL_VERIFYHOST,0L);
189	  r=curl_easy_perform(t->curl);
190	  if(r!=CURLE_OK){DOUBAO_ERR("doubao:TLS fail:%s(%d)",curl_easy_strerror(r),(int)r);
191	    voice_transport_close(t);return-EIO;}
192	  r=curl_easy_getinfo(t->curl,CURLINFO_ACTIVESOCKET,&t->fd);
193	  if(r!=CURLE_OK||t->fd==CURL_SOCKET_BAD){
194	    DOUBAO_ERR("doubao:no sock");voice_transport_close(t);return-EIO;}
195	  /* Drain TLS post-handshake data (NewSessionTicket etc.) BEFORE ws_upgrade
196	   * so we don't accidentally consume WebSocket-level frames. */
197	  { int drained=0;
198	    while(drained<32768){char sink[256];size_t nr=0;
199	      if(curl_easy_recv(t->curl,sink,sizeof(sink),&nr)!=CURLE_OK||nr==0)break;
200	      drained+=(int)nr;}
