221	  uint8_t*d,size_t c,int ms){
222	  int r,start;if(!t||!t->curl||!op||!d||c==0)return-EINVAL;
223	  if(t->pbf_len>0){
224	    for(start=0;start<t->pbf_len-1;start++)
225	      if(t->pbf[start]==0x82) break;
226	    if(start<t->pbf_len-1){
227	      int n=t->pbf_len-start<(int)c?t->pbf_len-start:(int)c;
228	      memcpy(d,t->pbf+start,n);t->pbf_len=0;*op=VOICE_WS_BINARY;
229	      return n;}
230	    t->pbf_len=0;}
231	  r=ws_recv(t->curl,t->fd,d,c,ms);
232	  if(r==-ETIMEDOUT)return 0;                 /* 干净超时:无数据,让上层继续等 */
233	  if(r==-ECONNRESET){*op=VOICE_WS_CLOSE;return r;}  /* 连接已死 → 重连 */
234	  if(r==-EMSGSIZE)return 0;                  /* 超大帧丢弃,不断连 */
