878	static int session_loop(voice_transport_t *transport, const char *session_id)
879	{
880	  voice_capture_t *capture = NULL;
881	  voice_player_t *player = NULL;
882	  uint8_t audio[DOUBAO_CAPTURE_PACKET_BYTES];
883	  const uint8_t silence[DOUBAO_CAPTURE_PACKET_BYTES] = {0};
