897	  set_state(is_talking() ? DOUBAO_VOICE_CONNECTING : DOUBAO_VOICE_IDLE, NULL);
898	  DOUBAO_LOG("full-duplex connection established, standing by");
899	
900	  while (!is_shutdown())
901	    {
902	      bool talking = is_talking();
903	
904	      /* 用户暂停:停止全双工,保留连接 */
905	      if (take_stop_playback())
906	        {
907	          if (player) { voice_player_abort(player); player = NULL; }
908	          if (capture) { voice_capture_close(capture); capture = NULL; }
909	          turn_open = false;
910	          chat_ended = false;
911	          discard_turn_audio = true;
912	          set_state(DOUBAO_VOICE_IDLE, NULL);
913	        }
914	
915	      /* 音乐抢占:立即停播、丢弃残留 TTS、回 IDLE */
916	      if (take_abort_playback())
917	        {
918	          if (player) { voice_player_abort(player); player = NULL; }
919	          turn_open = false;
920	          chat_ended = false;
