922	          set_state(is_talking() ? DOUBAO_VOICE_LISTENING
923	                                 : DOUBAO_VOICE_IDLE, NULL);
924	        }
925	
926	      /* 对话开始/停止边沿 */
927	      if (talking && !was_talking)
928	        {
929	#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_106_WAKEUP
930	          /* 开麦前等唤醒线程释放麦克风(它每圈轮询 talking, 看到即停,
931	           * 正常交接 ~200ms)。超时兜底: 唤醒线程卡死时放弃等待强开,
932	           * 否则会话永远起不来。 */
933	          {
934	            uint64_t wait_start = now_ms();
935	            while (wakeup_is_recording() && !is_shutdown() &&
936	                   now_ms() - wait_start < DOUBAO_MIC_HANDOFF_TIMEOUT_MS)
937	              {
938	                usleep(20 * 1000);
939	              }
940	            if (wakeup_is_recording())
941	              {
942	                DOUBAO_LOG("mic handoff: wakeup still recording after %dms, "
943	                           "opening anyway", DOUBAO_MIC_HANDOFF_TIMEOUT_MS);
944	              }
945	            else if (now_ms() - wait_start >= 20)
946	              {
947	                DOUBAO_LOG("mic handoff: waited %llums for wakeup release",
948	                           (unsigned long long)(now_ms() - wait_start));
949	              }
950	          }
951	#endif
952	          ret = voice_capture_open(&capture, g_voice.config.capture_device,
953	                                   DOUBAO_CAPTURE_RATE, DOUBAO_CAPTURE_CHANNELS,
954	                                   DOUBAO_CAPTURE_BITS);
955	          if (ret < 0)
956	            {
957	              set_state(DOUBAO_VOICE_ERROR, "麦克风不可用");
958	              return RC_STOP;
