1	/****************************************************************************
2	 * app/home_scense/ui_voice.c
3	 * AI conversation home page below the shared status bar.
4	 *
5	 * 多轮对话历史:每轮追加"你/豆包"两条气泡,历史保留、自动滚到底。
6	 * 按钮为点击切换(点一下开始录音 / 再点一下结束并等待回复),配合常驻会话:
7	 * 应用启动即连接豆包,每次录音只是同一连接上的新一轮,无需每轮重连。
8	 ****************************************************************************/
9	
10	#include "ui_voice.h"
11	#include "main.h"
12	#include "wifi_status.h"
13	#include "doubao/doubao_voice.h"
14	
15	#include <string.h>
16	
17	static lv_obj_t *g_messages;
18	static lv_obj_t *g_action;
19	static lv_obj_t *g_action_label;
20	static lv_obj_t *g_state_label;
21	
22	/* 当前轮的气泡(实时更新);turn_seq 变化即沉淀为历史、清引用 */
23	static lv_obj_t *g_cur_user_bubble;
24	static lv_obj_t *g_cur_ai_bubble;
25	static unsigned  g_cur_turn;
26	static char g_last_user[DOUBAO_TEXT_MAX];
27	static char g_last_reply[DOUBAO_REPLY_MAX];
28	
29	/* 新增/更新气泡:传入已存在的 bubble 则更新其文字,否则新建并返回。 */
30	static lv_obj_t *set_bubble(lv_obj_t *existing, const char *prefix,
31	                            const char *text, bool user)
32	{
33	    lv_obj_t *bubble;
34	    lv_obj_t *label;
35	
36	    if (!text || !text[0]) return existing;
37	
38	    if (existing) {
39	        label = lv_obj_get_child(existing, 0);
40	        if (label) lv_label_set_text_fmt(label, "%s%s", prefix, text);
41	        lv_obj_scroll_to_view(existing, LV_ANIM_ON);
42	        return existing;
43	    }
44	
45	    bubble = lv_obj_create(g_messages);
46	    lv_obj_set_width(bubble, 220);
47	    lv_obj_set_height(bubble, LV_SIZE_CONTENT);
48	    lv_obj_set_style_bg_color(bubble,
49	                              user ? lv_color_hex(0x1F618D) :
50	                                     lv_color_hex(0x273746), 0);
51	    lv_obj_set_style_bg_opa(bubble, LV_OPA_COVER, 0);
52	    lv_obj_set_style_border_width(bubble, 0, 0);
53	    lv_obj_set_style_radius(bubble, 8, 0);
54	    lv_obj_set_style_pad_all(bubble, 7, 0);
55	    lv_obj_set_style_margin_top(bubble, 4, 0);
56	    lv_obj_set_style_margin_bottom(bubble, 4, 0);
57	    lv_obj_set_style_margin_left(bubble, user ? 78 : 4, 0);
58	    lv_obj_set_style_margin_right(bubble, user ? 4 : 78, 0);
59	    lv_obj_clear_flag(bubble, LV_OBJ_FLAG_SCROLLABLE);
60	
61	    label = lv_label_create(bubble);
62	    lv_obj_set_width(label, 205);
63	    lv_label_set_text_fmt(label, "%s%s", prefix, text);
64	    lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
65	    lv_obj_set_style_text_font(label, g_misans_normal_12, 0);
66	    lv_obj_set_style_text_color(label, lv_color_hex(0xF7F9F9), 0);
67	    lv_obj_scroll_to_view(bubble, LV_ANIM_ON);
68	    return bubble;
69	}
70	
71	static const char *status_text(doubao_voice_state_t state)
72	{
73	    switch (state) {
74	    case DOUBAO_VOICE_UNCONFIGURED: return "请先配置豆包凭证";
75	    case DOUBAO_VOICE_IDLE: return "点击说话";
76	    case DOUBAO_VOICE_CONNECTING: return "正在连接豆包…";
77	    case DOUBAO_VOICE_LISTENING: return "聆听中…请说话";
78	    case DOUBAO_VOICE_RECORDING: return "正在识别…";
79	    case DOUBAO_VOICE_WAITING_RESPONSE: return "思考中…";
80	    case DOUBAO_VOICE_PLAYING: return "豆包正在回答…";
81	    case DOUBAO_VOICE_ERROR: return "语音服务发生错误";
82	    default: return "";
83	    }
84	}
85	
86	/* 全双工:点击切换会话。待命(未 talking)点击 → 开始连续对话;对话中(任一
87	 * 聆听/识别/思考/回答态)点击 → 停止会话。用 doubao_voice_is_talking() 判定,
88	 * 不再维护本地 toggle,避免与真实状态错位。 */
89	static void action_click_cb(lv_event_t *event)
90	{
91	    static uint32_t last_click;
92	    uint32_t now;
93	
94	    (void)event;
95	    home_record_activity();
96	
97	    /* 点击去抖:触摸屏偶尔把一次点击弹成两次 CLICKED。350ms 内重复忽略。 */
98	    now = lv_tick_get();
99	    if (now - last_click < 350) {
100	        return;
101	    }
102	    last_click = now;
103	
104	    if (!wifi_status_is_connected()) {
105	        return;
106	    }
107	    if (doubao_voice_is_talking()) {
108	        (void)doubao_voice_stop();
109	    } else {
110	        (void)doubao_voice_start();
111	    }
112	}
113	
114	void ui_voice_create(lv_obj_t *parent)
115	{
116	    g_messages = lv_obj_create(parent);
117	    lv_obj_set_size(g_messages, SCREEN_WIDTH - 16, 150);
118	    lv_obj_align(g_messages, LV_ALIGN_TOP_MID, 0, 34);
119	    lv_obj_set_style_bg_opa(g_messages, LV_OPA_TRANSP, 0);
120	    lv_obj_set_style_border_width(g_messages, 0, 0);
121	    lv_obj_set_style_pad_all(g_messages, 2, 0);
122	    lv_obj_set_flex_flow(g_messages, LV_FLEX_FLOW_COLUMN);
123	    lv_obj_set_scroll_dir(g_messages, LV_DIR_VER);
124	
125	    g_state_label = lv_label_create(parent);
126	    lv_obj_set_width(g_state_label, SCREEN_WIDTH - 24);
127	    lv_obj_align(g_state_label, LV_ALIGN_BOTTOM_MID, 0, -48);
128	    lv_obj_set_style_text_font(g_state_label, g_misans_normal_11, 0);
129	    lv_obj_set_style_text_align(g_state_label, LV_TEXT_ALIGN_CENTER, 0);
130	    lv_obj_set_style_text_color(g_state_label, lv_color_hex(0xAED6F1), 0);
131	
132	    g_action = lv_button_create(parent);
133	    lv_obj_set_size(g_action, SCREEN_WIDTH - 16, 36);
134	    lv_obj_align(g_action, LV_ALIGN_BOTTOM_MID, 0, -7);
135	    lv_obj_set_style_bg_color(g_action, lv_color_hex(0x1F618D), 0);
136	    lv_obj_set_style_border_width(g_action, 0, 0);
137	    lv_obj_set_style_radius(g_action, 8, 0);
138	    lv_obj_add_event_cb(g_action, action_click_cb, LV_EVENT_CLICKED, NULL);
139	    g_action_label = lv_label_create(g_action);
140	    lv_obj_set_style_text_font(g_action_label, g_misans_normal_16, 0);
141	    lv_obj_set_style_text_color(g_action_label, lv_color_hex(0xF7F9F9), 0);
142	    lv_obj_center(g_action_label);
143	}
144	
145	void ui_voice_refresh(lv_timer_t *timer)
146	{
147	    /* snapshot 含 assistant_text[DOUBAO_REPLY_MAX=8192],放栈上约 9KB,叠加
148	     * LVGL 主线程调用链易压爆 100KB 栈。改 static:refresh 由 LVGL 单线程
149	     * 周期调用,无并发,与 g_last_user/g_last_reply 一致。 */
150	    static doubao_voice_snapshot_t snapshot;
151	
152	    (void)timer;
153	    if (!g_action) return;
154	    doubao_voice_get_snapshot(&snapshot);
155	
156	    /* 新一轮开始:上一轮气泡已沉淀为历史,清空当前轮引用 */
157	    if (snapshot.turn_seq != g_cur_turn) {
158	        g_cur_turn = snapshot.turn_seq;
159	        g_cur_user_bubble = NULL;
160	        g_cur_ai_bubble = NULL;
161	        g_last_user[0] = '\0';
162	        g_last_reply[0] = '\0';
163	    }
164	
165	    if (snapshot.user_text[0] && strcmp(snapshot.user_text, g_last_user) != 0) {
166	        strncpy(g_last_user, snapshot.user_text, sizeof(g_last_user) - 1);
167	        g_cur_user_bubble = set_bubble(g_cur_user_bubble, "你：",
168	                                       snapshot.user_text, true);
169	    }
170	    if (snapshot.assistant_text[0] &&
171	        strcmp(snapshot.assistant_text, g_last_reply) != 0) {
172	        strncpy(g_last_reply, snapshot.assistant_text, sizeof(g_last_reply) - 1);
173	        g_cur_ai_bubble = set_bubble(g_cur_ai_bubble, "豆包：",
174	                                     snapshot.assistant_text, false);
175	    }
176	
177	    lv_label_set_text(g_state_label,
178	                      snapshot.state == DOUBAO_VOICE_ERROR &&
179	                      snapshot.error_text[0] ? snapshot.error_text :
180	                      status_text(snapshot.state));
181	
182	    /* 全双工按钮:
183	     *  - 未配置 / Wi-Fi 未连 / 连接中 → 禁用,提示原因
184	     *  - 对话中(talking:聆听/识别/思考/回答任一态)→ "停止对话"(红),可点
185	     *  - 待命(IDLE)→ "开始对话"(蓝),可点
186	     *  - ERROR → "点击重试"(橙),可点(触发重新开始) */
187	    if (snapshot.state == DOUBAO_VOICE_UNCONFIGURED) {
188	        lv_label_set_text(g_action_label, "请先配置豆包凭证");
189	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
190	        lv_obj_add_state(g_action, LV_STATE_DISABLED);
191	    } else if (!wifi_status_is_connected()) {
192	        lv_label_set_text(g_action_label, "Wi-Fi 未连接");
193	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
194	        lv_obj_add_state(g_action, LV_STATE_DISABLED);
195	    } else if (snapshot.state == DOUBAO_VOICE_CONNECTING) {
196	        lv_label_set_text(g_action_label, "连接中…");
197	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x566573), 0);
198	        lv_obj_add_state(g_action, LV_STATE_DISABLED);
199	    } else if (doubao_voice_is_talking()) {
200	        lv_label_set_text(g_action_label, "停止对话");
201	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0xC0392B), 0);
202	        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
203	    } else if (snapshot.state == DOUBAO_VOICE_ERROR) {
204	        lv_label_set_text(g_action_label, "点击重试");
205	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0xD68910), 0);
206	        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
207	    } else {
208	        lv_label_set_text(g_action_label, "开始对话");
209	        lv_obj_set_style_bg_color(g_action, lv_color_hex(0x1F618D), 0);
210	        lv_obj_clear_state(g_action, LV_STATE_DISABLED);
211	    }
212	}
